# EvoAgent diff_parser.py — parse_unified_diff() 核心逻辑
# 输入：原始 unified diff 字符串
# 输出：ParsedDiff(files=[...], added_lines=[ChangedLine(path, line, content), ...])

def parse_unified_diff(diff: str) -> ParsedDiff:
    files = []
    added = []
    current_path = ""
    new_line = 0          # 当前新文件行号
    in_hunk = False

    for raw in diff.splitlines():
        if raw.startswith("+++ "):
            current_path = raw[4:].strip()
            if current_path.startswith("b/"):
                current_path = current_path[2:]  # 去掉 git 的 b/ 前缀
            files.append(current_path)
            in_hunk = False
            continue

        match = HUNK.match(raw)  # 匹配 @@ -1,6 +1,8 @@ 格式
        if match:
            new_line = int(match.group(1))  # 从 hunk 头提取新文件起始行号
            in_hunk = True
            continue

        if not in_hunk:
            continue

        if raw.startswith("+") and not raw.startswith("+++"):
            # 新增行：保存 path + line + content
            added.append(ChangedLine(current_path, new_line, raw[1:]))
            new_line += 1
        elif raw.startswith("-"):
            continue        # 删除行：丢弃
        elif raw.startswith("\\ No newline"):
            continue        # 换行符标记：丢弃
        else:
            new_line += 1   # 上下文行：只更新行号，内容丢弃

    return ParsedDiff(files=files, added_lines=added)

