# 放宽版匹配算法（用于跨系统对比）
# 不要求 CWE 匹配，仅按 path + line 匹配

def relaxed_one_to_one_match(expected, predicted, line_tolerance=2):
    """
    与 EvoAgent 的 one_to_one_match 的区别：
    - 原版：path + line + CWE 三者都匹配才算 TP
    - 放宽版：path + line 匹配即可（不要求 CWE）

    这更公平，因为 Cloud Factory 不使用 CWE 体系。
    """
    edges = {}
    for ei, truth in enumerate(expected):
        truth_path = truth["path"]
        start, end = int(truth["start_line"]), int(truth["end_line"])
        options = []
        for pi, finding in enumerate(predicted):
            if finding["path"] != truth_path:
                continue
            line = finding["line"]
            if start <= line <= end:
                distance = 0
            else:
                distance = min(abs(line - start), abs(line - end))
            if distance <= line_tolerance:
                options.append((pi, distance))
        edges[ei] = sorted(options, key=lambda x: (x[1], x[0]))
    # 匈牙利算法（最大匹配）
    owner = {}
    def assign(ei, visited):
        for pi, _ in edges.get(ei, []):
            if pi in visited:
                continue
            visited.add(pi)
            if pi not in owner or assign(owner[pi], visited):
                owner[pi] = ei
                return True
        return False
    for ei in sorted(range(len(expected)), key=lambda i: len(edges[i])):
        assign(ei, set())
    return len(owner)  # TP count

# 改进方案：在 diff_parser.py 中新增 annotate_diff()
# 保留上下文行，标注 [OLD:n] / [NEW:n] / [OLD:n,NEW:m]
# 与现有 parse_unified_diff() 并存，不破坏现有接口

def annotate_diff(diff_text: str) -> str:
    """将 unified diff 转为标注格式，保留上下文行"""
    lines = []
    old_line = new_line = None
    for raw in diff_text.splitlines():
        if raw.startswith("diff --git ") or raw.startswith("Binary files "):
            old_line = new_line = None
            lines.append(raw)
            continue
        m = re.match(r"^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@", raw)
        if m:
            old_line, new_line = int(m.group(1)), int(m.group(2))
            lines.append(raw)
            continue
        if old_line is None or new_line is None:
            lines.append(raw)
            continue
        ch, text = raw[:1], raw[1:]
        if ch == "-":
            lines.append(f"[OLD:{old_line}] {text}")
            old_line += 1
        elif ch == "+":
            lines.append(f"[NEW:{new_line}] {text}")
            new_line += 1
        elif ch == " ":
            lines.append(f"[OLD:{old_line},NEW:{new_line}] {text}")
            old_line += 1; new_line += 1
        else:
            lines.append(raw)
    return "\n".join(lines)

# 改进方案：在 _parse_findings() 中增加丢弃日志
# 当前行为：静默丢弃（LLM 不知道为什么被过滤）
# 改进后：记录丢弃原因，输出到 trace/日志

def _parse_findings(self, result, parsed):
    valid_locations = {(item.path, item.line) for item in parsed.added_lines}
    findings = []
    discarded = []  # 新增：记录被丢弃的 Finding
    for raw in result.get("findings", []):
        path = str(raw.get("path", ""))
        line = int(raw.get("line", 0))
        if (path, line) not in valid_locations:
            discarded.append({
                "path": path, "line": line,
                "reason": "not in added_lines",
                "rule_id": raw.get("rule_id", "unknown")
            })
            continue
        findings.append(Finding(...))
    if discarded:
        logger.warning(f"Discarded {len(discarded)} findings not in added_lines: {discarded}")
    return findings

# 改进方案：config.py 新增分级模型配置
# 不破坏现有配置，向后兼容

@dataclass(frozen=True)
class Settings:
    # ... 现有配置 ...
    llm_model: str                          # 主模型（Specialist 审查）
    llm_model_critic: str = ""              # 新增：Critic 模型（可选）
    llm_model_verifier: str = ""            # 新增：Verifier 模型（可选）

    def resolved_llm_critic(self) -> dict:
        """如果配置了分级模型则使用，否则降级到主模型"""
        if self.llm_model_critic:
            return self._build_llm_config(self.llm_model_critic)
        return self.resolved_llm()  # 降级

    def resolved_llm_verifier(self) -> dict:
        if self.llm_model_verifier:
            return self._build_llm_config(self.llm_model_verifier)
        return self.resolved_llm()  # 降级

